class Solution {
  public int countGroups(int[] position, int[] speed, int distance) {
    int n = position.length;
    int[] prev = new int[n], next = new int[n];
    boolean[] alive = new boolean[n];
    for (int i = 0; i < n; i++) {
      prev[i] = i - 1;
      next[i] = i + 1 < n ? i + 1 : -1;
      alive[i] = true;
    }
    // event = {numerator, denominator, left, right}
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Long.compare(a[0] * b[1], b[0] * a[1]));
    for (int i = 0; i + 1 < n; i++) schedule(pq, position, speed, distance, i, i + 1, 0, 1);
    int groups = n;
    while (!pq.isEmpty()) {
      long num = pq.peek()[0], den = pq.peek()[1];
      List<long[]> batch = new ArrayList<>();
      while (!pq.isEmpty() && pq.peek()[0] * den == num * pq.peek()[1]) batch.add(pq.poll());
      // merges happening at the same instant are decided on the structure before any of them is
      // applied
      List<long[]> valid = new ArrayList<>();
      for (long[] e : batch) {
        int a = (int) e[2], b = (int) e[3];
        if (alive[a] && alive[b] && next[a] == b) valid.add(e);
      }
      for (long[] e : valid) {
        int a = (int) e[2];
        if (!alive[a]) continue;
        alive[a] = false;
        groups--;
        int p = prev[a], b = next[a];
        if (p >= 0) next[p] = b;
        prev[b] = p;
      }
      for (long[] e : valid) {
        int b = (int) e[3];
        if (alive[b] && prev[b] >= 0) schedule(pq, position, speed, distance, prev[b], b, num, den);
      }
    }
    return groups;
  }

  private static void schedule(
      java.util.PriorityQueue<long[]> pq,
      int[] pos,
      int[] speed,
      int distance,
      int a,
      int b,
      long curNum,
      long curDen) {
    long gap = (long) pos[b] - pos[a];
    long num, den;
    if (gap <= distance) {
      num = 0;
      den = 1;
    } else if (speed[a] > speed[b]) {
      num = gap - distance;
      den = (long) speed[a] - speed[b];
    } else return;
    if (num * curDen < curNum * den) {
      num = curNum;
      den = curDen;
    }
    pq.add(new long[] {num, den, a, b});
  }
}
